import {validateMessage} from './validation.js';
import type {ListSessionsMessage, SessionListMessage, WireSessionSummary} from '../../index.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and yields a frame with type user_message', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects the retired send_message alias rather than rewriting it', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result.valid).toBe(false);
  });

  it('drops an extra field the wire type does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('accepts a list_sessions frame with or without limit and before, strips extra keys, and rejects malformed ones', () => {
    const bare: ListSessionsMessage = {type: 'list_sessions'};
    const paged: ListSessionsMessage = {
      type: 'list_sessions',
      limit: 10,
      before: {updatedAt: '2026-01-01T00:00:05.000Z', sessionId: 's1'},
    };
    const summary: WireSessionSummary = {
      sessionId: 's1',
      createdAt: '2026-01-01T00:00:00.000Z',
      updatedAt: '2026-01-01T00:00:05.000Z',
      entryCount: 1,
    };
    const response: SessionListMessage = {type: 'session_list', sessions: [summary]};
    const rejected = [
      {type: 'list_sessions', limit: -1},
      {type: 'list_sessions', limit: 1.5},
      {type: 'list_sessions', limit: Number.NaN},
      {type: 'list_sessions', limit: Number.POSITIVE_INFINITY},
      {type: 'list_sessions', limit: '10'},
      {type: 'list_sessions', before: null},
      {type: 'list_sessions', before: 's1'},
      {type: 'list_sessions', before: []},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z'}},
      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: '', sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: 1700000000000, sessionId: 's1'}},
    ];

    expect({
      bare: validateMessage({...bare, userId: 'u2'}),
      zero: validateMessage({type: 'list_sessions', limit: 0}),
      paged: validateMessage({
        ...paged,
        before: {...paged.before, extra: 'ignored'},
      }),
      responseType: response.type,
      allRejected: rejected.every(frame => !validateMessage(frame).valid),
    }).toEqual({
      bare: {valid: true, data: {type: 'list_sessions'}},
      zero: {valid: true, data: {type: 'list_sessions', limit: 0}},
      paged: {valid: true, data: paged},
      responseType: 'session_list',
      allRejected: true,
    });
  });
});

